commit 6c7b4bed37f30707319ec5210b049777a291e5c3
Author: Jakub Jelen <jjelen@redhat.com>
Date:   Tue Oct 29 09:56:50 2019 +0100

    pkcs15*: Avoid null dereference from fuzzers

    Thanks oss-fuzz.

    Fixes: https://bugs.chromium.org/p/oss-fuzz/issues/detail?id=18591

diff --git a/src/libopensc/pkcs15-cert.c b/src/libopensc/pkcs15-cert.c
index 1a187f41..6f7c50c3 100644
--- a/src/libopensc/pkcs15-cert.c
+++ b/src/libopensc/pkcs15-cert.c
@@ -479,7 +479,7 @@ sc_pkcs15_decode_cdf_entry(struct sc_pkcs15_card *p15card, struct sc_pkcs15_obje
                return r;
        LOG_TEST_RET(ctx, r, "ASN.1 decoding failed");

-       if (!p15card->app || !p15card->app->ddo.aid.len)   {
+       if ((!p15card->app || !p15card->app->ddo.aid.len) && p15card->file_app) {
                r = sc_pkcs15_make_absolute_path(&p15card->file_app->path, &info.path);
                LOG_TEST_RET(ctx, r, "Cannot make absolute path");
        }
diff --git a/src/libopensc/pkcs15-data.c b/src/libopensc/pkcs15-data.c
index 636968ac..61e18c6c 100644
--- a/src/libopensc/pkcs15-data.c
+++ b/src/libopensc/pkcs15-data.c
@@ -123,7 +123,7 @@ int sc_pkcs15_decode_dodf_entry(struct sc_pkcs15_card *p15card,
                return r;
        LOG_TEST_RET(ctx, r, "ASN.1 decoding failed");

-       if (!p15card->app || !p15card->app->ddo.aid.len)   {
+       if ((!p15card->app || !p15card->app->ddo.aid.len) && p15card->file_app)   {
                r = sc_pkcs15_make_absolute_path(&p15card->file_app->path, &info.path);
                if (r < 0)
                        return r;
diff --git a/src/libopensc/pkcs15-pin.c b/src/libopensc/pkcs15-pin.c
index 07387c5a..8b7e5ac9 100644
--- a/src/libopensc/pkcs15-pin.c
+++ b/src/libopensc/pkcs15-pin.c
@@ -176,7 +176,7 @@ sc_pkcs15_decode_aodf_entry(struct sc_pkcs15_card *p15card, struct sc_pkcs15_obj
                                /* Give priority to AID defined in the application DDO */
                                if (p15card->app && p15card->app->ddo.aid.len)
                                        info.path.aid = p15card->app->ddo.aid;
-                               else if (p15card->file_app->path.len)
+                               else if (p15card->file_app && p15card->file_app->path.len)
                                        info.path = p15card->file_app->path;
                        }
                }
diff --git a/src/libopensc/pkcs15-pubkey.c b/src/libopensc/pkcs15-pubkey.c
index 96cee4eb..32a6e94f 100644
--- a/src/libopensc/pkcs15-pubkey.c
+++ b/src/libopensc/pkcs15-pubkey.c
@@ -340,7 +340,7 @@ int sc_pkcs15_decode_pukdf_entry(struct sc_pkcs15_card *p15card,
                obj->type = SC_PKCS15_TYPE_PUBKEY_DSA;
        }

-       if (!p15card->app || !p15card->app->ddo.aid.len)   {
+       if ((!p15card->app || !p15card->app->ddo.aid.len) && p15card->file_app) {
                r = sc_pkcs15_make_absolute_path(&p15card->file_app->path, &info->path);
                if (r < 0) {
                        goto err;
diff --git a/src/libopensc/pkcs15.c b/src/libopensc/pkcs15.c
index 68022697..e6970e8c 100644
--- a/src/libopensc/pkcs15.c
+++ b/src/libopensc/pkcs15.c
@@ -607,12 +607,14 @@ parse_odf(const unsigned char * buf, size_t buflen, struct sc_pkcs15_card *p15ca
                if (r < 0)
                        return r;
                type = r;
-               r = sc_pkcs15_make_absolute_path(&p15card->file_app->path, &path);
-               if (r < 0)
-                       return r;
-               r = sc_pkcs15_add_df(p15card, odf_indexes[type], &path);
-               if (r)
-                       return r;
+               if (p15card->file_app) {
+                       r = sc_pkcs15_make_absolute_path(&p15card->file_app->path, &path);
+                       if (r < 0)
+                               return r;
+                       r = sc_pkcs15_add_df(p15card, odf_indexes[type], &path);
+                       if (r)
+                               return r;
+               }
        }
        return 0;
 }
